// DisabledTenants is the resolver for the disabledTenants field: the
// system-only liveness lookup the other services' auth path and tenant
// middleware call through the gateway. Wraps handlers.DisabledTenants
// (soft-deleted-visible tenant table read) behind the system-user guard.
func (r *queryResolver) DisabledTenants(ctx context.Context, ids []uuid.UUID) ([]uuid.UUID, error) {
	if !authn.ForContext(ctx).IsSystemUser() {
		return nil, fmt.Errorf("disabledTenants: %w", authn.ErrSystemCallerRequired)
	}
	return mgmthandlers.DisabledTenants(ctx, r.client, ids)
}
